mapper.select:
SELECT s.id, s.community_id, s.community_name, s.title, s.start_at, s.end_at, s.capacity, s.remaining_seats

ORDER BY s.score DESC, s.created_at DESC, s.id DESC
LIMIT #{limit} OFFSET #{offset}

